<?php
declare(strict_types=1);
require_once __DIR__.'/includes/config.php';check_login();
$role=(string)($_SESSION['role_name']??$_SESSION['role']??'');if(!in_array($role,['Administrator','Finance','Accountant'],true)){http_response_code(403);exit('Finance access required.');}
if(!isset($conn)||!$conn instanceof mysqli){http_response_code(500);exit('Database connection unavailable.');}
if(empty($_SESSION['csrf_token']))$_SESSION['csrf_token']=bin2hex(random_bytes(32));
$currencies=['UGX'=>'Ugandan Shilling','USD'=>'US Dollar','EUR'=>'Euro','GBP'=>'British Pound','KES'=>'Kenyan Shilling','TZS'=>'Tanzanian Shilling','RWF'=>'Rwandan Franc','ETB'=>'Ethiopian Birr','CAD'=>'Canadian Dollar','AUD'=>'Australian Dollar'];
$message='';
if(($_GET['template']??'')==='1'){header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="project-program-budget-template.csv"');$out=fopen('php://output','wb');fputcsv($out,['entity_type','entity_code','activity_name','fiscal_year','currency','allocated_amount']);fputcsv($out,['Project','PRJ-001','Example activity',date('Y'),'UGX','1000000']);fputcsv($out,['Program','PRG-001','Example activity',date('Y'),'USD','5000']);fclose($out);exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!hash_equals((string)$_SESSION['csrf_token'],(string)($_POST['csrf_token']??''))){http_response_code(419);exit('Invalid form token.');}
 $action=(string)($_POST['action']??'');$incoming=[];
 if($action==='save')$incoming[]=['entity_type'=>(string)($_POST['entity_type']??''),'entity_code'=>trim((string)($_POST['entity_code']??'')),'activity_name'=>trim((string)($_POST['activity_name']??'')),'fiscal_year'=>(string)($_POST['fiscal_year']??''),'currency'=>strtoupper(trim((string)($_POST['currency']??''))),'allocated_amount'=>(string)($_POST['allocated_amount']??'')];
 elseif($action==='import'){
  $file=$_FILES['budget_file']??null;if(!$file||$file['error']!==UPLOAD_ERR_OK||strtolower(pathinfo((string)$file['name'],PATHINFO_EXTENSION))!=='csv')$message='Choose a valid CSV file.';
  else{$fh=fopen((string)$file['tmp_name'],'rb');$headers=$fh?fgetcsv($fh):false;$required=['entity_type','entity_code','activity_name','fiscal_year','currency','allocated_amount'];if(!is_array($headers)||array_map(static fn($v)=>strtolower(trim((string)$v)),$headers)!==$required)$message='CSV headers must be: '.implode(',',$required).'.';else{while(($line=fgetcsv($fh))!==false){if(count($line)!==count($required)){$message='A CSV row has the wrong number of columns.';break;}$incoming[]=array_combine($required,array_map('trim',$line));if(count($incoming)>1000){$message='The upload limit is 1,000 rows.';break;}}}if($fh)fclose($fh);}
 }else $message='Unknown budget action.';
 if($message===''&&!$incoming)$message='No budget rows were provided.';
 if($message==='' ){$validated=[];foreach($incoming as $row){$entity=$row['entity_type'];$code=trim($row['entity_code']);$activity=trim($row['activity_name']);$year=filter_var($row['fiscal_year'],FILTER_VALIDATE_INT);$currency=strtoupper(trim($row['currency']));$amount=filter_var($row['allocated_amount'],FILTER_VALIDATE_FLOAT);
  if(!in_array($entity,['Project','Program'],true)||$code===''||$activity===''||$year===false||$year<2000||$year>2100||!isset($currencies[$currency])||$amount===false||$amount<0){$message='A budget row has invalid values. Nothing was saved.';break;}
  $table=$entity==='Project'?'projects':'programs';$key=$entity==='Project'?'project_id':'id';$codeColumn=$entity==='Project'?'project_code':'program_code';$find=$conn->prepare("SELECT {$key} id FROM {$table} WHERE {$codeColumn}=? LIMIT 1");$find->bind_param('s',$code);$find->execute();$found=$find->get_result()->fetch_assoc();$find->close();if(!$found){$message='Unknown '.$entity.' code '.$code.'. Nothing was saved.';break;}
  $validated[]=['entity'=>$entity,'id'=>(int)$found['id'],'activity'=>$activity,'year'=>(int)$year,'currency'=>$currency,'amount'=>(float)$amount];
 }
 if($message===''&&$validated){$editor=(int)$_SESSION['user_id'];$conn->begin_transaction();try{foreach($validated as $row){$check=$conn->prepare("SELECT COALESCE(SUM(requested_amount),0) committed FROM activity_event_requests WHERE entity_type=? AND entity_id=? AND activity_name=? AND currency=? AND YEAR(start_date)=? AND status IN ('Director Approval','Approved')");$check->bind_param('sissi',$row['entity'],$row['id'],$row['activity'],$row['currency'],$row['year']);$check->execute();$committed=(float)($check->get_result()->fetch_assoc()['committed']??0);$check->close();if($row['amount']<$committed)throw new RuntimeException('Allocation for '.$row['activity'].' cannot be below committed expenditure.');$save=$conn->prepare('INSERT INTO project_program_budget_lines (entity_type,entity_id,activity_name,fiscal_year,currency,allocated_amount,updated_by) VALUES (?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE currency=VALUES(currency),allocated_amount=VALUES(allocated_amount),updated_by=VALUES(updated_by)');$save->bind_param('sisisdi',$row['entity'],$row['id'],$row['activity'],$row['year'],$row['currency'],$row['amount'],$editor);if(!$save->execute())throw new RuntimeException('A budget line could not be saved.');$save->close();}$conn->commit();$message=count($validated).' budget line(s) saved.';}catch(Throwable $e){$conn->rollback();$message=$e instanceof RuntimeException?$e->getMessage():'Budget save failed. No rows were saved.';}}
 }
}
$projects=$conn->query('SELECT project_code code,project_name name FROM projects ORDER BY project_name');$programs=$conn->query('SELECT program_code code,program_name name FROM programs ORDER BY program_name');
$lines=$conn->query("SELECT b.*,CASE WHEN b.entity_type='Project' THEN p.project_code ELSE pr.program_code END entity_code,CASE WHEN b.entity_type='Project' THEN p.project_name ELSE pr.program_name END entity_name,COALESCE((SELECT SUM(r.requested_amount) FROM activity_event_requests r WHERE r.entity_type=b.entity_type AND r.entity_id=b.entity_id AND r.activity_name=b.activity_name AND r.currency=b.currency AND YEAR(r.start_date)=b.fiscal_year AND r.status IN ('Director Approval','Approved')),0) committed FROM project_program_budget_lines b LEFT JOIN projects p ON b.entity_type='Project' AND p.project_id=b.entity_id LEFT JOIN programs pr ON b.entity_type='Program' AND pr.id=b.entity_id ORDER BY b.entity_type,entity_code,b.fiscal_year DESC,b.activity_name");
$rows=$lines?$lines->fetch_all(MYSQLI_ASSOC):[];$counts=['lines'=>count($rows),'UGX_allocated'=>0.0,'UGX_committed'=>0.0];$byCurrency=[];foreach($rows as $row){$c=$row['currency'];$byCurrency[$c]=($byCurrency[$c]??0)+(float)$row['allocated_amount'];if($c==='UGX'){$counts['UGX_allocated']+=(float)$row['allocated_amount'];$counts['UGX_committed']+=(float)$row['committed'];}}
$page_title='Manage Project/Program Budgets';require_once __DIR__.'/includes/header.php';function mpb_h($v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
?>
<style>
