.mpb-card{background:var(--surface-card);border:1px solid var(--border);border-radius:var(--radius-lg);padding:22px;box-shadow:var(--shadow-sm)}
.mpb-actions{display:flex;flex-wrap:wrap;gap:12px;align-items:center}.mpb form{display:flex;flex-wrap:wrap;align-items:end;gap:14px;margin:14px 0}.mpb label{display:grid;gap:6px;flex:1 1 190px;font-weight:600;color:var(--ink-700)}
.mpb input,.mpb select{min-height:42px;padding:9px 12px;border:1px solid var(--border);border-radius:var(--radius-sm);background:var(--surface-card);color:var(--ink-900);font:inherit}.mpb button,.mpb .mpb-button{min-height:42px;padding:9px 16px;border:0;border-radius:var(--radius-sm);background:var(--brand-600);color:var(--ink-0);text-decoration:none;font-weight:600;cursor:pointer;display:inline-flex;align-items:center;justify-content:center}.mpb button:hover,.mpb .mpb-button:hover{background:var(--brand-700)}
.mpb-table-wrap{overflow:auto}.mpb table{width:100%;min-width:900px;border-collapse:collapse}.mpb th,.mpb td{padding:12px;border-bottom:1px solid var(--border);text-align:left;color:var(--ink-700)}.mpb th{background:var(--surface-hover);color:var(--ink-900);text-transform:uppercase;font-size:.8rem}.mpb .note{color:var(--ink-400)}.mpb-modal{margin:auto;width:min(900px,calc(100vw - 24px));max-height:90vh;overflow:auto;padding:24px;border:1px solid var(--border);border-radius:var(--radius-lg);background:var(--surface-card);color:var(--ink-900);box-shadow:var(--shadow-xl)}.mpb-modal::backdrop{background:rgba(13,17,23,.58)}.mpb-modal-head{display:flex;justify-content:space-between;align-items:center;gap:12px}.mpb-modal-head button{background:var(--surface-hover);color:var(--ink-900)}
@media(max-width:700px){.mpb{padding:14px}.mpb-card,.mpb-modal{padding:16px}.mpb-actions>*{width:100%}}
</style>
<div class="mpb"><h1>Manage Project/Program Budgets</h1><?php if($message!==''):?><div class="alert alert-info" role="status"><?=mpb_h($message)?></div><?php endif;?>
<div class="stats-grid reports-stats"><div class="stat-card"><div class="stat-icon bg-blue"><i class="fas fa-list" aria-hidden="true"></i></div><div class="stat-info"><span class="stat-label">Budget Lines</span><span class="stat-value"><?=number_format(count($rows))?></span></div></div><div class="stat-card"><div class="stat-icon bg-green"><i class="fas fa-coins" aria-hidden="true"></i></div><div class="stat-info"><span class="stat-label">Allocated (UGX)</span><span class="stat-value"><?=number_format($counts['UGX_allocated'],0)?></span></div></div><div class="stat-card"><div class="stat-icon bg-amber"><i class="fas fa-hand-holding-dollar" aria-hidden="true"></i></div><div class="stat-info"><span class="stat-label">Committed (UGX)</span><span class="stat-value"><?=number_format($counts['UGX_committed'],0)?></span></div></div><div class="stat-card"><div class="stat-icon bg-teal"><i class="fas fa-wallet" aria-hidden="true"></i></div><div class="stat-info"><span class="stat-label">Available (UGX)</span><span class="stat-value"><?=number_format($counts['UGX_allocated']-$counts['UGX_committed'],0)?></span></div></div><?php foreach($byCurrency as $currency=>$amount):if($currency==='UGX')continue;?><div class="stat-card"><div class="stat-icon bg-purple"><i class="fas fa-money-bill-wave" aria-hidden="true"></i></div><div class="stat-info"><span class="stat-label">Allocated (<?=mpb_h($currency)?>)</span><span class="stat-value"><?=number_format($amount,2)?></span></div></div><?php endforeach;?></div>
<section class="mpb-card"><h2>Budget management</h2><p class="note">Add a new budget line, update an existing allocation, or import multiple lines with a CSV file.</p><div class="mpb-actions"><button type="button" data-mpb-open="budgetModal">Add / edit budget line</button><button type="button" class="mpb-button" data-mpb-open="importModal">Import budget lines</button><a class="mpb-button" href="manage-project-program-budgets?template=1">Download CSV template</a></div></section>
<dialog class="mpb-modal" id="budgetModal"><div class="mpb-modal-head"><h2>Add or update a budget line</h2><button type="button" data-mpb-close>Close</button></div><p class="note">Matching entity code, activity, and fiscal year updates the existing allocation.</p><form method="post" id="budgetForm"><input type="hidden" name="csrf_token" value="<?=mpb_h($_SESSION['csrf_token'])?>"><input type="hidden" name="action" value="save"><label>Entity type<select name="entity_type" required><option>Project</option><option>Program</option></select></label><label>Project/program code<select name="entity_code" required><option value="">Select code</option><?php if($projects)while($r=$projects->fetch_assoc()):?><option data-entity="Project" value="<?=mpb_h($r['code'])?>">Project · <?=mpb_h($r['code'])?> — <?=mpb_h($r['name'])?></option><?php endwhile;?><?php if($programs)while($r=$programs->fetch_assoc()):?><option data-entity="Program" value="<?=mpb_h($r['code'])?>">Program · <?=mpb_h($r['code'])?> — <?=mpb_h($r['name'])?></option><?php endwhile;?></select></label><label>Activity/budget line<input required name="activity_name" maxlength="255"></label><label>Fiscal year<input required name="fiscal_year" type="number" min="2000" max="2100" value="<?=date('Y')?>"></label><label>Currency<select name="currency" required><?php foreach($currencies as $code=>$label):?><option value="<?=mpb_h($code)?>"><?=mpb_h($code)?> — <?=mpb_h($label)?></option><?php endforeach;?></select></label><label>Allocation<input required name="allocated_amount" type="number" min="0" step="0.01"></label><button type="submit">Save budget</button></form></dialog>
<dialog class="mpb-modal" id="importModal"><div class="mpb-modal-head"><h2>Import budget lines</h2><button type="button" data-mpb-close>Close</button></div><p class="note">Required CSV columns: entity_type, entity_code, activity_name, fiscal_year, currency, allocated_amount. Up to 1,000 rows; all rows validate before saving.</p><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf_token" value="<?=mpb_h($_SESSION['csrf_token'])?>"><input type="hidden" name="action" value="import"><label>Budget CSV<input type="file" name="budget_file" accept=".csv,text/csv" required></label><button type="submit">Upload and import</button></form></dialog>
<section class="mpb-card"><h2>Budget lines</h2><div class="mpb-table-wrap"><table><thead><tr><th>Entity code/name</th><th>Activity</th><th>Year</th><th>Currency</th><th>Allocation</th><th>Committed</th><th>Available</th><th></th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="8">No budget lines found.</td></tr><?php endif;?><?php foreach($rows as $r):?><tr><td><strong><?=mpb_h($r['entity_type'])?> <?=mpb_h($r['entity_code']??'')?></strong><br><?=mpb_h($r['entity_name']??'')?></td><td><?=mpb_h($r['activity_name'])?></td><td><?=$r['fiscal_year']?></td><td><?=mpb_h($r['currency'])?></td><td><?=number_format((float)$r['allocated_amount'],2)?></td><td><?=number_format((float)$r['committed'],2)?></td><td><?=number_format((float)$r['allocated_amount']-(float)$r['committed'],2)?></td><td><button type="button" class="mpb-edit" data-type="<?=mpb_h($r['entity_type'])?>" data-code="<?=mpb_h($r['entity_code']??'')?>" data-activity="<?=mpb_h($r['activity_name'])?>" data-year="<?=$r['fiscal_year']?>" data-currency="<?=mpb_h($r['currency'])?>" data-amount="<?=$r['allocated_amount']?>">Edit</button></td></tr><?php endforeach;?></tbody></table></div></section></div>
<script>
const budgetModal=document.getElementById('budgetModal'),budgetForm=document.getElementById('budgetForm'),typeSelect=budgetForm.querySelector('[name="entity_type"]'),codeSelect=budgetForm.querySelector('[name="entity_code"]');
function filterCodes(){for(const option of codeSelect.options)if(option.value)option.hidden=option.dataset.entity!==typeSelect.value;}
typeSelect.addEventListener('change',filterCodes);filterCodes();
document.querySelectorAll('[data-mpb-open]').forEach(button=>button.addEventListener('click',()=>document.getElementById(button.dataset.mpbOpen).showModal()));document.querySelectorAll('[data-mpb-close]').forEach(button=>button.addEventListener('click',()=>button.closest('dialog').close()));
document.querySelectorAll('.mpb-edit').forEach(button=>button.addEventListener('click',()=>{typeSelect.value=button.dataset.type;filterCodes();codeSelect.value=button.dataset.code;budgetForm.querySelector('[name="activity_name"]').value=button.dataset.activity;budgetForm.querySelector('[name="fiscal_year"]').value=button.dataset.year;budgetForm.querySelector('[name="currency"]').value=button.dataset.currency;budgetForm.querySelector('[name="allocated_amount"]').value=button.dataset.amount;budgetModal.showModal();}));
</script>
